import {readFileSync,writeFileSync} from "node:fs";
import {gunzipSync} from "node:zlib";
import {observationAt,R21_SYMBOLS,type R21Series} from "../lib/stable4-r21-market-observation";
const F=String.raw`C:\tmp\disdex-d126-crossrunner-research-20261126\R21_TS_RAW_INPUT_20261127`,H=3600000,M=300000;
const data:Record<string,R21Series>={};
for(const s of ["BTC",...R21_SYMBOLS]) data[s]=JSON.parse(gunzipSync(readFileSync(F+"/"+s+".json.gz")).toString("utf8"));
const begin=Date.parse("2025-10-01T00:00:00Z"),end=Date.parse("2026-10-01T00:00:00Z");
const expected=JSON.parse(readFileSync(F+"/expected.json","utf8"));
const key=(x:any)=>[x.symbol,x.route,x.ts].join("|");
const actual:any[]=[];let rejects=0;
for(let t=begin;t<end;t+=H){
 for(const x of observationAt(data,t)){
  const s=data[x.symbol.replace(/USDT$/,"")],k=(t-s.startM)/M;
  const duration=x.route==="R21_OLD24"?72:48;
  // Historical evaluation availability only; NEVER used by the observation kernel.
  if(t+duration*H>=end||k<0||k+duration*12>=s.m.length||s.m.slice(k,k+duration*12+1).some(r=>!r||!r.slice(0,4).every(Number.isFinite))){rejects++;continue;}
  actual.push(x);
 }
}
const e=new Set(expected.map(key)),a=new Set(actual.map(key));
const missing=[...e].filter(x=>!a.has(x)),extra=[...a].filter(x=>!e.has(x));
const out={expected:expected.length,actual:actual.length,unique:a.size,missing,extra,excludedByHistoricalExitCoverage:rejects,matched:[...e].filter(x=>a.has(x)).length};
writeFileSync(F+"/parity_v1.json",JSON.stringify(out,null,2));console.log(JSON.stringify(out));if(missing.length||extra.length||a.size!==actual.length)process.exitCode=1;

