import {publicGetBars,type PublicSymbol} from "../lib/stable4-p91-public-observation-feed";
import {R21_SYMBOLS,normalizeR21Raw} from "../lib/stable4-r21-market-observation";
const H=3600000,t=Math.floor(Date.now()/H)*H;
async function main(){
 const results:any[]=[];
 for(const s of ["BTC",...R21_SYMBOLS]){
  const symbol=(s+"USDT") as PublicSymbol;
  const tasks=[["ASTER","1h",t-192*H],["BINANCE","1h",t-192*H],["ASTER","5m",t-51*H]] as const;
  const a=await Promise.allSettled(tasks.map(([venue,i,start])=>publicGetBars(venue,symbol,i,start,t)));
  const row:any={symbol,feeds:a.map((x,i)=>({venue:tasks[i][0],interval:tasks[i][1],ok:x.status==="fulfilled",detail:x.status==="fulfilled"?x.value.length:String(x.reason)}))};
  if(a.every(x=>x.status==="fulfilled"))try{const v=a.map(x=>x.status==="fulfilled"?x.value:[]);normalizeR21Raw(v[0],v[2],v[1],t);row.normalized=true;}catch(e){row.normalized=false;row.reason=String(e);}
  results.push(row);console.log(JSON.stringify(row));
 }
 console.log("SUMMARY "+JSON.stringify({boundary:t,symbols:results.length,feedsPassed:results.flatMap(x=>x.feeds).filter(x=>x.ok).length,normalized:results.filter(x=>x.normalized).length}));
}
main().catch(e=>{console.error(e);process.exitCode=1});
